command:
$ErrorActionPreference = "Stop"
git fetch origin main work/dispatch-only-windows-build --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }

Write-Host "LOCAL_BRANCH=$(git branch --show-current)"
Write-Host "LOCAL_HEAD=$(git rev-parse HEAD)"
Write-Host "ORIGIN_MAIN=$(git rev-parse origin/main)"
Write-Host "TARGET=$(git rev-parse origin/work/dispatch-only-windows-build)"

$status = @(git status --short)
if ($status.Count -ne 0) {
  $status | ForEach-Object { Write-Host $_ }
  throw "persistent checkout has unexpected local changes"
}

if ((git rev-parse origin/main).Trim() -ne "f51953eaac16eb9f6ab3aaebfb83be4c65875beb") {
  throw "main moved after dispatch-only policy snapshot"
}

if ((git branch --show-current) -ne "work/dispatch-only-windows-build") {
  if (git show-ref --verify --quiet refs/heads/work/dispatch-only-windows-build) {
    git checkout work/dispatch-only-windows-build
  } else {
    git checkout -b work/dispatch-only-windows-build --track origin/work/dispatch-only-windows-build
  }
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout target branch" }
}
git merge --ff-only origin/work/dispatch-only-windows-build
if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward target branch" }

python -X utf8 -m unittest tests.winui.test_remote_windows_task_contract tests.winui.test_validation_scope_contract
if ($LASTEXITCODE -ne 0) { throw "focused source contracts failed" }

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }

Write-Host "DISPATCH_ONLY_POLICY_SOURCE_PASS"
